from collections import Counter

def transform(grid):
    # The demos consistently use 0 and 5 as the two background/noise colors.
    # Each 3x3 patch is reduced to its non-background object color, if any.
    out = []
    h, w = len(grid), len(grid[0])
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(grid[y][x]
                for y in range(r, min(r + 3, h))
                for x in range(c, min(c + 3, w))
                if grid[y][x] not in (0, 5))
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
